def _bottles(n):
    if n == 0:
        return "no more bottles of beer"
    if n == 1:
        return "1 bottle of beer"
    return f"{n} bottles of beer"


def _verse(n):
    if n == 0:
        return [
            "No more bottles of beer on the wall, no more bottles of beer.",
            "Go to the store and buy some more, 99 bottles of beer on the wall.",
        ]
    if n == 1:
        return [
            "1 bottle of beer on the wall, 1 bottle of beer.",
            "Take it down and pass it around, no more bottles of beer on the wall.",
        ]
    return [
        f"{n} bottles of beer on the wall, {n} bottles of beer.",
        f"Take one down and pass it around, {n - 1} bottles of beer on the wall.",
    ]


def recite(start, take=1):
    lines = []
    for i, n in enumerate(range(start, start - take, -1)):
        if i > 0:
            lines.append("")
        lines.extend(_verse(n))
    return lines

